#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum CardType {
    Master,
    Action,
    ActionModifier,
    Reaction,
    Combat,
    PoliticalAction,
    Ally,
    Equipment,
    Retainer,
    Event,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Cost {
    None,
    Fixed(u8),
    /// Printed "X": chosen when the card is played.
    X,
}

/// Printed labels the rules key on (uniqueness, one hunting ground per
/// turn, one vehicle, one archetype, trifle accounting, …).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Label {
    Unique,
    Location,
    HuntingGround,
    Weapon,
    Gun,
    Vehicle,
    Electronic,
    Archetype,
    Trifle,
    Gehenna,
    Title,
    OutOfTurn,
    Frenzy,
    Grapple,
    Aim,
    Discipline,
    Mortal,
    Animal,
    Ghoul,
    Zombie,
    Wraith,
    Werewolf,
    Mage,
    Demon,
    Infernal,
    MultiDiscipline,
    RequiresAnarch,
    MakesAnarch,
    OperationAntigen,
    Condemnation,
    Derivative,
}

/// One playable mode of a card: its bracket tags as printed (`DOM`,
/// `ani`, `pro`, `COMBAT`; lower case = basic, upper = superior; empty for an
/// untagged card), the windows it is playable in, and per-mode flags.
/// Windows and flags are names from data/window-matrix-reviewed.csv. Two
/// discipline tags on one mode mean *either* unless the card is a `combo`
/// or `Label::MultiDiscipline` (one mode per set of Disciplines used).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Mode {
    pub tags: &'static [&'static str],
    pub windows: &'static [&'static str],
    pub flags: &'static [&'static str],
}

/// An ally's or retainer's printed type line: its starting life, and an
/// ally's strength and bleed (0 for a retainer, which has neither).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Body {
    pub life: u8,
    pub strength: u8,
    pub bleed: u8,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct LibraryCard {
    pub id: u32,
    pub name: &'static str,
    pub types: &'static [CardType],
    /// Discipline requirement(s) at basic level, as printed (`dom`, `aus`, …).
    pub disciplines: &'static [&'static str],
    /// Clan requirement(s), if any.
    pub clans: &'static [&'static str],
    pub blood_cost: Cost,
    pub pool_cost: Cost,
    pub burn_option: bool,
    /// Combo card: every listed discipline is required (KRCG `combo`).
    pub combo: bool,
    pub labels: &'static [Label],
    /// Allies and retainers: the printed type line.
    pub body: Option<Body>,
    pub modes: &'static [Mode],
    /// The Sabbat path icon (KRCG `path`): a vampire following it plays
    /// the card (rules-qa 49.7).
    pub path: Option<&'static str>,
}

